fn yarra(arr: &Vec<char>) -> Vec<char> {
    // Pre-allocate a vector with the same length as the input
    let mut out = Vec::with_capacity(arr.len());
    // Iterate over the input in reverse order, cloning each character
    for &c in arr.iter().rev() {
        out.push(c);
    }
    out
}

fn main() {
    let input = vec!['h', 'e', 'l', 'l', 'o'];
    let output = yarra(&input);
    println!("{:?}", output); // prints ['o', 'l', 'l', 'e', 'h']
}